/**
 * @summary Create a draft change request with a before/after preview (owner/admin only)
 */
export const createAdDraftBodyIdempotencyKeyMax = 128;

export const createAdDraftBodyNameMax = 400;

export const createAdDraftBodyDailyBudgetMin = 0;

export const createAdDraftBodyLifetimeBudgetMin = 0;


export const createAdDraftBodyTextMax = 3000;

export const createAdDraftBodyTargetingLocationsMax = 50;

export const createAdDraftBodyTargetingIndustriesMax = 50;

export const createAdDraftBodyTargetingJobFunctionsMax = 50;

export const createAdDraftBodyTargetingTitlesMax = 50;



export const CreateAdDraftBody = zod.object({
  "connectionId": zod.number(),
  "targetType": zod.enum(['campaign', 'adset', 'ad', 'campaign_group', 'creative']).describe('campaign_group is LinkedIn-only (create and update); creative is LinkedIn-only (create, plus status-only updates).'),
  "action": zod.enum(['create', 'update']),
  "targetId": zod.string().optional().describe('Remote object id (required for update).'),
  "idempotencyKey": zod.string().max(createAdDraftBodyIdempotencyKeyMax).optional().describe('Client-supplied key to make retries safe; server generates one when omitted.'),
  "name": zod.string().max(createAdDraftBodyNameMax).optional(),
  "status": zod.enum(['ACTIVE', 'PAUSED', 'ARCHIVED']).optional().describe('ARCHIVED is only accepted for LinkedIn creative status updates.'),
  "objective": zod.string().optional().describe('Campaign objective (Meta create only), e.g. OUTCOME_TRAFFIC.'),
  "campaignGroupId": zod.string().optional().describe('LinkedIn only — campaign group to create the campaign in (required for LinkedIn creates).'),
  "dailyBudget": zod.number().min(createAdDraftBodyDailyBudgetMin).nullish().describe('Daily budget in minor currency units.'),
  "lifetimeBudget": zod.number().min(createAdDraftBodyLifetimeBudgetMin).nullish().describe('Lifetime budget in minor currency units.'),
  "removeLifetimeBudget": zod.boolean().optional().describe('LinkedIn campaign group updates only — remove the group\'s lifetime budget entirely (mutually exclusive with lifetimeBudget).'),
  "startTime": zod.string().nullish().describe('ISO-8601 schedule start.'),
  "stopTime": zod.string().nullish().describe('ISO-8601 schedule end.'),
  "bidAmount": zod.number().min(1).nullish().describe('Meta ad set updates only — bid cap \/ cost cap amount in minor currency units.'),
  "bidStrategy": zod.union([zod.literal('LOWEST_COST_WITHOUT_CAP'),zod.literal('LOWEST_COST_WITH_BID_CAP'),zod.literal('COST_CAP'),zod.literal(null)]).nullish().describe('Meta ad set updates only — bid strategy (requires the ad set to hold its own budget).'),
  "campaignId": zod.string().optional().describe('LinkedIn creative creates — the campaign the creative attaches to.'),
  "text": zod.string().max(createAdDraftBodyTextMax).optional().describe('LinkedIn creative creates — the sponsored post\'s text.'),
  "imagePath": zod.string().nullish().describe('LinkedIn creative creates — content library image path (`\/objects\/<tenantId>\/uploads\/<uuid>`).'),
  "landingUrl": zod.string().nullish().describe('LinkedIn creative creates — click-through landing page URL (https).'),
  "targetingLocations": zod.array(zod.object({
  "urn": zod.string().describe('LinkedIn targeting entity URN, e.g. urn:li:geo:103644278 or urn:li:industry:4.'),
  "name": zod.string()
})).max(createAdDraftBodyTargetingLocationsMax).optional().describe('LinkedIn campaigns — replacement location targeting (geo URNs picked via targeting search). Must be non-empty when provided.'),
  "targetingIndustries": zod.array(zod.object({
  "urn": zod.string().describe('LinkedIn targeting entity URN, e.g. urn:li:geo:103644278 or urn:li:industry:4.'),
  "name": zod.string()
})).max(createAdDraftBodyTargetingIndustriesMax).optional().describe('LinkedIn campaign updates — replacement industry targeting (urn:li:industry URNs). An empty array clears the facet.'),
  "targetingJobFunctions": zod.array(zod.object({
  "urn": zod.string().describe('LinkedIn targeting entity URN, e.g. urn:li:geo:103644278 or urn:li:industry:4.'),
  "name": zod.string()
})).max(createAdDraftBodyTargetingJobFunctionsMax).optional().describe('LinkedIn campaign updates — replacement job function targeting (urn:li:function URNs). An empty array clears the facet.'),
  "targetingTitles": zod.array(zod.object({
  "urn": zod.string().describe('LinkedIn targeting entity URN, e.g. urn:li:geo:103644278 or urn:li:industry:4.'),
  "name": zod.string()
})).max(createAdDraftBodyTargetingTitlesMax).optional().describe('LinkedIn campaign updates — replacement job title targeting (urn:li:title URNs). An empty array clears the facet.')
})

